<?php
declare(strict_types=1);
/** Atelier Wood MakeOS Quality — v0.7.4 */
function quality_root(): string { return data_root().'/private-domain/quality'; }
function quality_store_file(): string { return quality_root().'/quality.json'; }
function quality_media_dir(): string { return quality_root().'/evidence'; }
function quality_context(): string { return 'atelierwood:quality:v1'; }
function quality_ensure_dirs(): void { foreach([quality_root(),quality_media_dir()] as $d){if(!is_dir($d)&&!@mkdir($d,0750,true)&&!is_dir($d))throw new RuntimeException('Unable to create quality storage.');@chmod($d,0750);} }
function quality_empty(): array { return ['defects'=>[],'evidence'=>[],'lot_inspections'=>[],'events'=>[]]; }
function quality_store(): array { quality_ensure_dirs();try{$s=commerce_private_read(quality_store_file(),quality_context(),quality_empty());}catch(Throwable){$s=quality_empty();}return array_merge(quality_empty(),$s); }
function quality_mutate(callable $fn,string $reason): array { quality_ensure_dirs();$out=[];commerce_private_mutate(quality_store_file(),quality_context(),function(array $s)use($fn,&$out){$s=array_merge(quality_empty(),$s);$s=$fn($s);$out=$s;return$s;},$reason);return$out; }
function quality_defect_number(): string { return 'DEF-'.gmdate('ymd').'-'.strtoupper(substr(bin2hex(random_bytes(4)),0,8)); }
function quality_defects_for_job(string $jobGuid): array { $r=array_values(array_filter(quality_store()['defects'],fn($d)=>($d['job_guid']??'')===$jobGuid));usort($r,fn($a,$b)=>strcmp((string)$b['created_at'],(string)$a['created_at']));return$r; }
function quality_evidence_for_job(string $jobGuid): array { $r=array_values(array_filter(quality_store()['evidence'],fn($e)=>($e['job_guid']??'')===$jobGuid));usort($r,fn($a,$b)=>strcmp((string)$b['created_at'],(string)$a['created_at']));return$r; }
function quality_job_has_blocking_defects(string $jobGuid): bool { foreach(quality_defects_for_job($jobGuid) as $d)if(in_array(($d['severity']??''),['CRITICAL','MAJOR'],true)&&($d['status']??'')!=='RESOLVED')return true;return false; }
function quality_create_defect(string $jobGuid,array $input): array { require_admin();$job=makeos_job_by_guid($jobGuid);if(!$job)throw new RuntimeException('MakeOS job not found.');$severity=strtoupper(trim((string)($input['severity']??'MINOR')));if(!in_array($severity,['MINOR','MAJOR','CRITICAL'],true))throw new RuntimeException('Invalid defect severity.');$stage=strtoupper(trim((string)($input['stage']??($job['current_stage']??'QA'))));if(!in_array($stage,makeos_stages(),true))$stage='QA';$description=trim((string)($input['description']??''));if(text_len($description)<5)throw new RuntimeException('Describe the defect.');$d=['guid'=>uuidv7(),'number'=>quality_defect_number(),'job_guid'=>$jobGuid,'job_number'=>$job['number'],'stage'=>$stage,'category'=>strtoupper(trim((string)($input['category']??'WORKMANSHIP'))),'severity'=>$severity,'description'=>$description,'status'=>'OPEN','corrective_action'=>'','created_by'=>'admin:'.(admin_identity()['guid']??'unknown'),'created_at'=>gmdate('c'),'updated_at'=>gmdate('c'),'resolved_at'=>null];quality_mutate(function(array $s)use($d){$s['defects'][]=$d;return$s;},'quality.defect.create');return$d; }
function quality_update_defect(string $guid,string $action,string $note=''): array { require_admin();$action=strtoupper(trim($action));$updated=null;quality_mutate(function(array $s)use($guid,$action,$note,&$updated){foreach($s['defects'] as &$d)if(($d['guid']??'')===$guid){if(($d['status']??'')==='RESOLVED')throw new RuntimeException('Defect is already resolved.');if($action==='CORRECTIVE_ACTION'){$d['status']='CORRECTIVE_ACTION';$d['corrective_action']=trim($note);}elseif($action==='RESOLVE'){$d['status']='RESOLVED';$d['resolution_note']=trim($note);$d['resolved_at']=gmdate('c');}else throw new RuntimeException('Unsupported defect action.');$d['updated_at']=gmdate('c');$updated=$d;break;}return$s;},'quality.defect.update');if(!$updated)throw new RuntimeException('Defect not found.');return$updated; }
function quality_add_evidence(string $jobGuid,array $upload,string $stage,string $caption=''): array { require_admin();$job=makeos_job_by_guid($jobGuid);if(!$job)throw new RuntimeException('MakeOS job not found.');if(($upload['error']??UPLOAD_ERR_NO_FILE)!==UPLOAD_ERR_OK)throw new RuntimeException('Choose an image to upload.');$tmp=(string)($upload['tmp_name']??'');$size=(int)($upload['size']??0);if($size<=0||$size>8*1024*1024)throw new RuntimeException('Evidence image must be 8 MB or smaller.');$finfo=new finfo(FILEINFO_MIME_TYPE);$mime=(string)$finfo->file($tmp);$ext=['image/jpeg'=>'jpg','image/png'=>'png','image/webp'=>'webp'][$mime]??null;if(!$ext)throw new RuntimeException('Only JPEG, PNG or WebP evidence images are accepted.');$info=@getimagesize($tmp);if(!$info||($info[0]??0)<20||($info[1]??0)<20)throw new RuntimeException('Image signature/dimensions are invalid.');$stage=strtoupper(trim($stage));if(!in_array($stage,makeos_stages(),true))$stage=(string)($job['current_stage']??'QA');$guid=uuidv7();$name=$guid.'.'.$ext;$dest=quality_media_dir().'/'.$name;if(!@move_uploaded_file($tmp,$dest)){if(!@rename($tmp,$dest)&&!@copy($tmp,$dest))throw new RuntimeException('Unable to store evidence image.');}@chmod($dest,0640);$e=['guid'=>$guid,'job_guid'=>$jobGuid,'job_number'=>$job['number'],'stage'=>$stage,'caption'=>trim($caption),'mime'=>$mime,'file'=>$name,'bytes'=>filesize($dest)?:$size,'width'=>(int)$info[0],'height'=>(int)$info[1],'sha256'=>hash_file('sha256',$dest),'created_by'=>'admin:'.(admin_identity()['guid']??'unknown'),'created_at'=>gmdate('c')];quality_mutate(function(array $s)use($e){$s['evidence'][]=$e;return$s;},'quality.evidence.add');return$e; }
function quality_evidence_by_guid(string $guid): ?array { foreach(quality_store()['evidence'] as $e)if(($e['guid']??'')===$guid)return$e;return null; }
function quality_lot_inspect(string $lotGuid,string $decision,string $note=''): array { require_admin();$decision=strtoupper(trim($decision));if(!in_array($decision,['ACCEPTED','QUARANTINED','REJECTED'],true))throw new RuntimeException('Invalid lot quality decision.');$updated=null;procurement_mutate(function(array $s)use($lotGuid,$decision,&$updated){foreach($s['lots'] as &$lot)if(($lot['guid']??'')===$lotGuid){if((float)($lot['qty_reserved']??0)>0&&$decision!=='ACCEPTED')throw new RuntimeException('Release reserved stock before quarantining/rejecting this lot.');$lot['quality_status']=$decision;$updated=$lot;break;}return$s;},'quality.lot.inspect');if(!$updated)throw new RuntimeException('Lot not found.');$inspection=['guid'=>uuidv7(),'lot_guid'=>$lotGuid,'lot_number'=>$updated['lot_number'],'material_guid'=>$updated['material_guid'],'decision'=>$decision,'note'=>trim($note),'inspected_by'=>'admin:'.(admin_identity()['guid']??'unknown'),'inspected_at'=>gmdate('c')];quality_mutate(function(array $s)use($inspection){$s['lot_inspections'][]=$inspection;return$s;},'quality.lot.inspection.record');return$inspection; }
function quality_release_checks(): array { $s=quality_store();$unique=count(array_column($s['defects'],'number'))===count(array_unique(array_column($s['defects'],'number')));$files=true;$hash=true;foreach($s['evidence'] as $e){$p=quality_media_dir().'/'.($e['file']??'');if(!is_file($p)){$files=false;continue;}if(!hash_equals((string)($e['sha256']??''),(string)hash_file('sha256',$p)))$hash=false;}$raw=is_file(quality_store_file())?(string)file_get_contents(quality_store_file()):'';$encrypted=$raw===''||!str_contains($raw,'defects');return [
 ['name'=>'Quality store encryption','ok'=>$encrypted,'detail'=>'Quality/defect metadata is encrypted at rest.'],
 ['name'=>'Defect number uniqueness','ok'=>$unique,'detail'=>'Defect references are unique.'],
 ['name'=>'Production evidence file integrity','ok'=>$files&&$hash,'detail'=>'Every registered production photo exists and validates against its SHA-256 fingerprint.'],
 ['name'=>'QA blocking-defect policy','ok'=>function_exists('quality_job_has_blocking_defects'),'detail'=>'Major/critical open defects block final QA pass.'],
 ]; }
quality_ensure_dirs();
